import pyautogui
import cv2
import numpy as np
import time  
from datetime import datetime
import threading
import os

class ScreenRecorder:
    def __init__(self, output_path=None, fps=20.0):
        """  
        Cross-platform screen recording utility  
        
        Args:  
            output_path:  If it is a disk drive, or a custom output directory ending with '/' or '\\',
                will create avi file in it with default name,  f"recording_{datetime.now().strftime('%Y%m%d_%H%M%S')}.avi".
                If it is a file path (i.e., without ending '/', '\\' ), will create it as an avi file.
            fps: Frames per second  
        """
        # Screen dimensions
        screen_size = pyautogui.size()
        self.width, self.height = screen_size[0], screen_size[1]

        # Default output path
        default_recording_file_name = f"recording_{datetime.now().strftime('%Y%m%d_%H%M%S')}.avi"
        if not output_path:
            output_path = default_recording_file_name
        else:
            if len(output_path) == 2 and output_path[1] == ':' and os.name == 'nt':  
                output_path += os.sep
            if not output_path.endswith(('\\', '/', '.avi')):
                output_path = os.path.splitext(output_path)[0] + '.avi'
            elif output_path.endswith(('\\', '/' )):
                output_path = os.path.join(output_path, default_recording_file_name)
            parent_dir = os.path.dirname(output_path)
            if parent_dir:
                os.makedirs(name=parent_dir, exist_ok=True)
    
        # Video writer configuration  
        fourcc = cv2.VideoWriter_fourcc(*'XVID')  
        self.out = cv2.VideoWriter(output_path, fourcc, fps, (self.width, self.height))

        self.is_recording = False

    def start_recording(self):
        """Start screen recording"""  
        self.is_recording = True
        self._record_thread = threading.Thread(target=self._record_screen)
        self._record_thread.start()

    def stop_recording(self):
        """Stop screen recording"""  
        self.is_recording = False
        self._record_thread.join()
        self.out.release()
        cv2.destroyAllWindows()

    def _record_screen(self):
        """Internal screen recording method""" 
        while self.is_recording:
            # Capture screen
            img = pyautogui.screenshot()
            frame = np.array(img)

            # Convert RGB to BGR (OpenCV requirement)
            frame = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)

            # Write frame
            self.out.write(frame)
       
            # Optional: Control frame rate
            time.sleep(1/20)  # 20 FPS
